INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('X0JW5B2Y8B8', 1, '{"title":"猪肤汤","description":"<p>$u{猪肤}$w{一斤}。</p>\n<p> </p>\n<p>         右一味，以水一斗，煮取五升，去滓，加$u{白蜜}$w{一升}，$n{白粉}$w{五合}，熬香，和令相得，分温六服。(白粉即米粉)</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":186,"yaoCount":2,"drinkNum":6,"yaoList":["猪肤","白蜜"],"fangList":[],"fangYaoList":[{"yaoId":"0uQxJy23uFD","amount":"一斤","weight":null,"suffix":null,"showName":"猪肤","extraProcess":null},{"yaoId":"IHSagd4ikNY","amount":"一升","weight":null,"suffix":null,"showName":"白蜜","extraProcess":null}]}}', '2024-12-16T05:49:11.000Z', '2024-12-16T05:49:11.000Z', '2024-12-16T05:49:11.000Z', '$u{猪肤}$w{一斤}。 右一味，以水一斗，煮取五升，去滓，加$u{白蜜}$w{一升}，$n{白粉}$w{五合}，熬香，和令相得，分温六服。(白粉即米粉)', '2024-12-16T05:49:11.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('46VoH5cL6Q4', 1, '{"title":"甘草汤","description":"<p>$u{甘草}$w{二两}。</p>\n<p></p>\n<p>         右一味，以水三升，煮取一升半，去滓，温服七合，日二服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":187,"yaoCount":1,"drinkNum":2,"yaoList":["甘草"],"fangList":[],"fangYaoList":[{"yaoId":"vVJUANA6k8h","amount":"二两","weight":null,"suffix":null,"showName":"甘草","extraProcess":null}]}}', '2024-12-16T05:52:08.000Z', '2024-12-16T05:52:08.000Z', '2024-12-16T05:52:08.000Z', '$u{甘草}$w{二两}。 右一味，以水三升，煮取一升半，去滓，温服七合，日二服。', '2024-12-16T05:52:08.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3DfXe0q0eiO', 1, '{"title":"桔梗汤","description":"<p>$u{桔梗}$w{一两}、$u{甘草}$w{二两}。</p>\n<p></p>\n<p>       右二味，以水三升，煮取一升，去滓，温分再服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":188,"yaoCount":2,"drinkNum":2,"yaoList":["桔梗","甘草"],"fangList":[],"fangYaoList":[{"yaoId":"t7DkIvGNO8b","amount":"一两","weight":null,"suffix":null,"showName":"桔梗","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":"二两","weight":null,"suffix":null,"showName":"甘草","extraProcess":null}]}}', '2024-12-16T05:53:16.000Z', '2024-12-16T05:53:16.000Z', '2024-12-16T05:53:16.000Z', '$u{桔梗}$w{一两}、$u{甘草}$w{二两}。 右二味，以水三升，煮取一升，去滓，温分再服。', '2024-12-16T05:53:16.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VMtWS8C1Flk', 1, '{"title":"苦酒汤","description":"<p>$u{半夏}$w{十四枚 (洗破如枣核)}、$u{鸡子}$w{一枚 (去黄纳上$u{苦酒}着鸡子壳中)}。</p>\n<p></p>\n<p>        右二味，纳半夏，着苦酒中，以鸡子壳，置刀环中，安火上，令三沸，去滓，少少含咽之，不差，更作三剂。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":189,"yaoCount":3,"drinkNum":3,"yaoList":["半夏","鸡子","苦酒"],"fangList":[],"fangYaoList":[{"yaoId":"axI8tfBmKAx","amount":"十四枚 (洗破如枣核)","weight":null,"suffix":null,"showName":"半夏","extraProcess":null},{"yaoId":null,"amount":"一枚 (去黄纳上","weight":null,"suffix":null,"showName":"鸡子","extraProcess":null},{"yaoId":"uUYyOFNioq6","amount":null,"weight":null,"suffix":null,"showName":"苦酒","extraProcess":null}]}}', '2024-12-16T05:56:38.000Z', '2024-12-16T05:56:38.000Z', '2024-12-16T05:56:38.000Z', '$u{半夏}$w{十四枚 (洗破如枣核)}、$u{鸡子}$w{一枚 (去黄纳上$u{苦酒}着鸡子壳中)}。 右二味，纳半夏，着苦酒中，以鸡子壳，置刀环中，安火上，令三沸，去滓，少少含咽之，不差，更作三剂。', '2024-12-16T05:56:38.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kefSwYgWAKc', 1, '{"title":"半夏散","description":"<p>$u{半夏} }$w{(洗)}、$u{桂枝}、$u{甘草} }$w{(炙)}。</p>\n<p></p>\n<p>       右三味，$w{等分}，各别捣筛已，合治之，白饮和服方寸匙，日三服，若不能散服者，以水一升煎七沸，纳散两方寸匙，更煎三沸，下火令小冷，少少咽之。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":190,"yaoCount":3,"drinkNum":3,"yaoList":["半夏","桂枝","甘草"],"fangList":[],"fangYaoList":[{"yaoId":"axI8tfBmKAx","amount":null,"weight":null,"suffix":null,"showName":"半夏","extraProcess":null},{"yaoId":"7S7n1dzieYK","amount":null,"weight":null,"suffix":null,"showName":"桂枝","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":null,"weight":null,"suffix":null,"showName":"甘草","extraProcess":null}]}}', '2024-12-16T05:59:34.000Z', '2024-12-16T05:59:34.000Z', '2024-12-16T05:59:34.000Z', '$u{半夏} }$w{(洗)}、$u{桂枝}、$u{甘草} }$w{(炙)}。 右三味，$w{等分}，各别捣筛已，合治之，白饮和服方寸匙，日三服，若不能散服者，以水一升煎七沸，纳散两方寸匙，更煎三沸，下火令小冷，少少咽之。', '2024-12-16T05:59:34.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('b0ckBkoj3y6', 1, '{"title":"白通汤","description":"<p>$u{葱白}$w{四茎}、$u{干姜}$w{一两}、$u{附子}$w{一枚 (生用去皮破八片)}。</p>\n<p></p>\n<p>          右三味，以水三升，煮取一升，去滓，分温再服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":191,"yaoCount":3,"drinkNum":2,"yaoList":["葱白","干姜","附子"],"fangList":[],"fangYaoList":[{"yaoId":null,"amount":"四茎","weight":null,"suffix":null,"showName":"葱白","extraProcess":null},{"yaoId":"0p1dUWRsS6D","amount":"一两","weight":null,"suffix":null,"showName":"干姜","extraProcess":null},{"yaoId":"jT011T7yIVO","amount":"一枚 (生用去皮破八片)","weight":null,"suffix":null,"showName":"附子","extraProcess":null}]}}', '2024-12-16T06:01:21.000Z', '2024-12-16T06:01:21.000Z', '2024-12-16T06:01:21.000Z', '$u{葱白}$w{四茎}、$u{干姜}$w{一两}、$u{附子}$w{一枚 (生用去皮破八片)}。 右三味，以水三升，煮取一升，去滓，分温再服。', '2024-12-16T06:01:21.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kqLkVP0GZkH', 1, '{"title":"白通加猪胆汁汤","description":"<p>$u{葱白}$w{四茎}、$u{干姜}$w{一两}、$u{附子}$w{一枚 (生用去皮破八片)}、$u{人尿}$w{五合}、$u{猪胆汁}$w{一合}。</p>\n<p></p>\n<p>           右五味，以水三升，先煮三物，取一升，去滓，纳人尿，猪胆汁，和令相得，分温再服，若无胆汁亦可用。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":192,"yaoCount":5,"drinkNum":2,"yaoList":["葱白","干姜","附子","人尿","猪胆汁"],"fangList":[],"fangYaoList":[{"yaoId":null,"amount":"四茎","weight":null,"suffix":null,"showName":"葱白","extraProcess":null},{"yaoId":"0p1dUWRsS6D","amount":"一两","weight":null,"suffix":null,"showName":"干姜","extraProcess":null},{"yaoId":"jT011T7yIVO","amount":"一枚 (生用去皮破八片)","weight":null,"suffix":null,"showName":"附子","extraProcess":null},{"yaoId":"3mS1d7xGocT","amount":"五合","weight":null,"suffix":null,"showName":"人尿","extraProcess":null},{"yaoId":"KIP0kUQVkZG","amount":"一合","weight":null,"suffix":null,"showName":"猪胆汁","extraProcess":null}]}}', '2024-12-16T06:03:41.000Z', '2024-12-16T06:03:41.000Z', '2024-12-16T06:03:41.000Z', '$u{葱白}$w{四茎}、$u{干姜}$w{一两}、$u{附子}$w{一枚 (生用去皮破八片)}、$u{人尿}$w{五合}、$u{猪胆汁}$w{一合}。 右五味，以水三升，先煮三物，取一升，去滓，纳人尿，猪胆汁，和令相得，分温再服，若无胆汁亦可用。', '2024-12-16T06:03:41.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('K3Cuu7nYL8Y', 1, '{"title":"四逆散","description":"<p>$u{甘草}$w{二两 (炙)}、$u{附子}$w{大者一枚}、$u{干姜}$w{一两半}、$u{人参}$w{二两}。</p>\n<p></p>\n<p>       右四味，捣筛，白饮和服方寸匙，</p>\n<p>            咳者去$u{人参}加、$u{五味子}、$u{干姜}$w{各五分}，</p>\n<p>            并主下利；悸者，加$u{桂枝}$w{五分}；</p>\n<p>            小便不利者，加$u{茯苓}$w{五分}；</p>\n<p>            泄利下重者，先以水五升，煮$u{薤白}$w{三两}，取三升，去滓，以散三方寸匙纳汤中，煮取一升半，分温再服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":193,"yaoCount":4,"drinkNum":2,"yaoList":["甘草","附子","干姜","人参"],"fangList":[],"fangYaoList":[{"yaoId":"vVJUANA6k8h","amount":"二两 (炙)","weight":null,"suffix":null,"showName":"甘草","extraProcess":null},{"yaoId":"jT011T7yIVO","amount":"大者一枚","weight":null,"suffix":null,"showName":"附子","extraProcess":null},{"yaoId":"0p1dUWRsS6D","amount":"一两半","weight":null,"suffix":null,"showName":"干姜","extraProcess":null},{"yaoId":"GIXSHBaFv0L","amount":"二两","weight":null,"suffix":null,"showName":"人参","extraProcess":null}]}}', '2024-12-16T06:16:45.000Z', '2024-12-16T06:16:45.000Z', '2024-12-16T06:16:45.000Z', '$u{甘草}$w{二两 (炙)}、$u{附子}$w{大者一枚}、$u{干姜}$w{一两半}、$u{人参}$w{二两}。 右四味，捣筛，白饮和服方寸匙， 咳者去$u{人参}加、$u{五味子}、$u{干姜}$w{各五分}， 并主下利；悸者，加$u{桂枝}$w{五分}； 小便不利者，加$u{茯苓}$w{五分}； 泄利下重者，先以水五升，煮$u{薤白}$w{三两}，取三升，去滓，以散三方寸匙纳汤中，煮取一升半，分温再服。', '2024-12-16T06:16:45.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('a2UZ5YNKRkD', 1, '{"title":"当归四逆加人参附子汤","description":"<p>$u{当归}$w{三两}、$u{桂枝}$w{三两 (去皮)}、$u{芍药}$w{三两}、$u{细辛}$w{三两}、$u{甘草}$w{二两 (炙)}、$u{木通}$w{二两}、$u{大枣}$w{二十五枚 (劈)}、$u{人参}$w{三两}、$u{附子}$w{一枚 (炮去皮破八片)}。</p>\n<p></p>\n<p>         右九味，以水八升，煮取三升，去滓，温服一升，日三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":194,"yaoCount":9,"drinkNum":3,"yaoList":["当归","桂枝","芍药","细辛","甘草","木通","大枣","人参","附子"],"fangList":[],"fangYaoList":[{"yaoId":"JFnirDnffR9","amount":"三两","weight":null,"suffix":null,"showName":"当归","extraProcess":null},{"yaoId":"7S7n1dzieYK","amount":"三两 (去皮)","weight":null,"suffix":null,"showName":"桂枝","extraProcess":null},{"yaoId":"Ro0664U6sTQ","amount":"三两","weight":null,"suffix":null,"showName":"芍药","extraProcess":null},{"yaoId":"MCBshcFNHhk","amount":"三两","weight":null,"suffix":null,"showName":"细辛","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":"二两 (炙)","weight":null,"suffix":null,"showName":"甘草","extraProcess":null},{"yaoId":null,"amount":"二两","weight":null,"suffix":null,"showName":"木通","extraProcess":null},{"yaoId":"JZ9gTmGblYB","amount":"二十五枚 (劈)","weight":null,"suffix":null,"showName":"大枣","extraProcess":null},{"yaoId":"GIXSHBaFv0L","amount":"三两","weight":null,"suffix":null,"showName":"人参","extraProcess":null},{"yaoId":"jT011T7yIVO","amount":"一枚 (炮去皮破八片)","weight":null,"suffix":null,"showName":"附子","extraProcess":null}]}}', '2024-12-16T06:34:39.000Z', '2024-12-16T06:34:39.000Z', '2024-12-16T06:34:39.000Z', '$u{当归}$w{三两}、$u{桂枝}$w{三两 (去皮)}、$u{芍药}$w{三两}、$u{细辛}$w{三两}、$u{甘草}$w{二两 (炙)}、$u{木通}$w{二两}、$u{大枣}$w{二十五枚 (劈)}、$u{人参}$w{三两}、$u{附子}$w{一枚 (炮去皮破八片)}。 右九味，以水八升，煮取三升，去滓，温服一升，日三服。', '2024-12-16T06:34:39.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
