INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Za3MCAJXAzR', 1, '{"title":"半夏干姜散","description":"<p>$u{半夏}、$u{干姜}$w{各等分}。右二味，杵为散，取方寸匙，浆水一升半，煮取七合，顿服之。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":205,"yaoCount":2,"drinkNum":2,"yaoList":["半夏","干姜"],"fangList":[],"fangYaoList":[{"yaoId":"axI8tfBmKAx","amount":null,"weight":null,"suffix":null,"showName":"半夏","extraProcess":null},{"yaoId":"0p1dUWRsS6D","amount":"各等分","weight":null,"suffix":null,"showName":"干姜","extraProcess":null}]}}', '2024-12-16T07:09:55.000Z', '2024-12-16T07:09:55.000Z', '2024-12-16T07:09:55.000Z', '$u{半夏}、$u{干姜}$w{各等分}。右二味，杵为散，取方寸匙，浆水一升半，煮取七合，顿服之。', '2024-12-16T07:09:55.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aRWUzir2vaC', 1, '{"title":"生姜半夏汤","description":"<p>$u{生姜}$w{一斤}、$u{半夏}$w{半升}。</p>\n<p></p>\n<p>        右二味，以水三升，先煮半夏，取二升，纳生姜汁，煮取一升，去滓，小冷，分四服，日三，夜一，呕止，停后服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":206,"yaoCount":2,"drinkNum":4,"yaoList":["生姜","半夏"],"fangList":[],"fangYaoList":[{"yaoId":"VcvhqvKkSct","amount":"一斤","weight":null,"suffix":null,"showName":"生姜","extraProcess":null},{"yaoId":"axI8tfBmKAx","amount":"半升","weight":null,"suffix":null,"showName":"半夏","extraProcess":null}]}}', '2024-12-16T07:11:41.000Z', '2024-12-16T07:11:41.000Z', '2024-12-16T07:11:41.000Z', '$u{生姜}$w{一斤}、$u{半夏}$w{半升}。 右二味，以水三升，先煮半夏，取二升，纳生姜汁，煮取一升，去滓，小冷，分四服，日三，夜一，呕止，停后服。', '2024-12-16T07:11:41.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('19jwMSLW8G6', 1, '{"title":"橘皮汤","description":"<p>$u{橘皮}$w{四两}、$u{生姜}$w{半斤}。</p>\n<p></p>\n<p>          右二味，以水七升，煮取三升，去滓，温服一升，下咽即愈。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":207,"yaoCount":2,"drinkNum":2,"yaoList":["橘皮","生姜"],"fangList":[],"fangYaoList":[{"yaoId":"216GW1qIoXb","amount":"四两","weight":null,"suffix":null,"showName":"橘皮","extraProcess":null},{"yaoId":"VcvhqvKkSct","amount":"半斤","weight":null,"suffix":null,"showName":"生姜","extraProcess":null}]}}', '2024-12-16T07:13:07.000Z', '2024-12-16T07:13:07.000Z', '2024-12-16T07:13:07.000Z', '$u{橘皮}$w{四两}、$u{生姜}$w{半斤}。 右二味，以水七升，煮取三升，去滓，温服一升，下咽即愈。', '2024-12-16T07:13:07.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cwe2H17QiYk', 1, '{"title":"橘皮竹茹汤","description":"<p>$u{橘皮}$w{二斤}、$u{竹茹}$w{二升}、$u{人参}$w{一两}、$u{甘草}$w{五两}、$u{生姜}$w{半斤}、$u{大枣}$w{三十枚}。</p>\n<p></p>\n<p>        右六味，以水一斗，煮取三升，去滓，温服一升，日三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":208,"yaoCount":6,"drinkNum":3,"yaoList":["橘皮","竹茹","人参","甘草","生姜","大枣"],"fangList":[],"fangYaoList":[{"yaoId":"216GW1qIoXb","amount":"二斤","weight":null,"suffix":null,"showName":"橘皮","extraProcess":null},{"yaoId":"aDnno23iRr4","amount":"二升","weight":null,"suffix":null,"showName":"竹茹","extraProcess":null},{"yaoId":"GIXSHBaFv0L","amount":"一两","weight":null,"suffix":null,"showName":"人参","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":"五两","weight":null,"suffix":null,"showName":"甘草","extraProcess":null},{"yaoId":"VcvhqvKkSct","amount":"半斤","weight":null,"suffix":null,"showName":"生姜","extraProcess":null},{"yaoId":"JZ9gTmGblYB","amount":"三十枚","weight":null,"suffix":null,"showName":"大枣","extraProcess":null}]}}', '2024-12-16T07:14:24.000Z', '2024-12-16T07:14:24.000Z', '2024-12-16T07:14:24.000Z', '$u{橘皮}$w{二斤}、$u{竹茹}$w{二升}、$u{人参}$w{一两}、$u{甘草}$w{五两}、$u{生姜}$w{半斤}、$u{大枣}$w{三十枚}。 右六味，以水一斗，煮取三升，去滓，温服一升，日三服。', '2024-12-16T07:14:24.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dHnKf3aX1YD', 1, '{"title":"黄连茯苓汤","description":"<p>$u{黄连}$w{二两}、$u{茯苓}$w{三两}、$u{阿胶}$w{一两半}、$u{芍药}$w{三两}、$u{黄芩}$w{三两}、$u{半夏}$w{一升}。</p>\n<p></p>\n<p>        右六味，以水一斗，先煮五味，取三升，去滓，纳胶烊消，分温三服。</p>\n<p></p>\n<p>            若胸中热甚者，加$u黄连}$w{一两}，合前成$m{三两}；</p>\n<p>            腹满者，加$u厚朴}$w{二两}；</p>\n<p>            人虚者，加$u甘草}$w{二两}，</p>\n<p>            渴者，去$u半夏}，加$u括蒌根}$w{二两}。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":209,"yaoCount":6,"drinkNum":3,"yaoList":["黄连","茯苓","阿胶","芍药","黄芩","半夏"],"fangList":[],"fangYaoList":[{"yaoId":"5GP5Zyu6577","amount":"二两","weight":null,"suffix":null,"showName":"黄连","extraProcess":null},{"yaoId":"VHE7Y68l232","amount":"三两","weight":null,"suffix":null,"showName":"茯苓","extraProcess":null},{"yaoId":"T3B7gaA2R03","amount":"一两半","weight":null,"suffix":null,"showName":"阿胶","extraProcess":null},{"yaoId":"Ro0664U6sTQ","amount":"三两","weight":null,"suffix":null,"showName":"芍药","extraProcess":null},{"yaoId":"fd3riAoOlLa","amount":"三两","weight":null,"suffix":null,"showName":"黄芩","extraProcess":null},{"yaoId":"axI8tfBmKAx","amount":"一升","weight":null,"suffix":null,"showName":"半夏","extraProcess":null}]}}', '2024-12-16T07:19:45.000Z', '2024-12-16T07:19:45.000Z', '2024-12-16T07:19:45.000Z', '$u{黄连}$w{二两}、$u{茯苓}$w{三两}、$u{阿胶}$w{一两半}、$u{芍药}$w{三两}、$u{黄芩}$w{三两}、$u{半夏}$w{一升}。 右六味，以水一斗，先煮五味，取三升，去滓，纳胶烊消，分温三服。 若胸中热甚者，加$u黄连}$w{一两}，合前成$m{三两}； 腹满者，加$u厚朴}$w{二两}； 人虚者，加$u甘草}$w{二两}， 渴者，去$u半夏}，加$u括蒌根}$w{二两}。', '2024-12-16T07:19:45.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gWEFClx8HBn', 1, '{"title":"甘草粉蜜汤","description":"<p>$u{甘草}$w{二两}、$u{白粉}$w{一两 (即铅粉)}、$u{蜜}$w{四两}。</p>\n<p></p>\n<p>       右三味，以水三升，先煮甘草，取二升，去滓，纳粉蜜搅令和，煎如薄粥，温服一升，差，止后服。</p>\n<p></p>\n<p>注：$a{“白粉”：会通本注“即铅粉”（另有猪肤汤亦用白粉，却注为米粉）。宋文清通过南阳风土习惯考证认为“小麦粉”。附：《成都中医学院学报》(1986.11.18)报道，四川省某县1970年7月发生一起应用甘草粉蜜汤集体驱蛔，因使用铅粉，致使接受该方的74人全部中毒，无一幸免。中毒者在服药时曾觉药有铅臭，数小时后心烦，轻微呕吐，胃中嘈杂不适。2～9天内先后不同程度出现头昏头痛，身软无力，懒言嗜睡，口臭流涎，口腔糜烂，食欲逐渐下降，胸腹胀满，四肢及眼胞浮肿。部分病例在牙龈边缘可见蓝灰色铅线。中毒者初起面色灰白少华，大便秘结；3～5天后部分病人面色发黄，甚至全身发黄；大便由秘结转溏泻，小便深黄量少。舌质：中毒初中期淡红，苔白滑或厚腻；中后期有少数患者出现舌绛少苔；脉象多虚弦、滑数无力或见有濡弱之脉。经用昆布、海藻、金钱草、板蓝根等加减治疗，除1例死亡外，全部治愈。据此，作者认为原方“粉”，应为米粉。}</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":210,"yaoCount":3,"drinkNum":2,"yaoList":["甘草","白粉","蜜"],"fangList":[],"fangYaoList":[{"yaoId":"vVJUANA6k8h","amount":"二两","weight":null,"suffix":null,"showName":"甘草","extraProcess":null},{"yaoId":"Ghsn25eutF9","amount":"一两 (即铅粉)","weight":null,"suffix":null,"showName":"白粉","extraProcess":null},{"yaoId":"IHSagd4ikNY","amount":"四两","weight":null,"suffix":null,"showName":"蜜","extraProcess":null}]}}', '2024-12-16T07:22:23.000Z', '2024-12-16T07:22:23.000Z', '2024-12-16T07:22:23.000Z', '$u{甘草}$w{二两}、$u{白粉}$w{一两 (即铅粉)}、$u{蜜}$w{四两}。 右三味，以水三升，先煮甘草，取二升，去滓，纳粉蜜搅令和，煎如薄粥，温服一升，差，止后服。 注：$a{“白粉”：会通本注“即铅粉”（另有猪肤汤亦用白粉，却注为米粉）。宋文清通过南阳风土习惯考证认为“小麦粉”。附：《成都中医学院学报》(1986.11.18)报道，四川省某县1970年7月发生一起应用甘草粉蜜汤集体驱蛔，因使用铅粉，致使接受该方的74人全部中毒，无一幸免。中毒者在服药时曾觉药有铅臭，数小时后心烦，轻微呕吐，胃中嘈杂不适。2～9天内先后不同程度出现头昏头痛，身软无力，懒言嗜睡，口臭流涎，口腔糜烂，食欲逐渐下降，胸腹胀满，四肢及眼胞浮肿。部分病例在牙龈边缘可见蓝灰色铅线。中毒者初起面色灰白少华，大便秘结；3～5天后部分病人面色发黄，甚至全身发黄；大便由秘结转溏泻，小便深黄量少。舌质：中毒初中期淡红，苔白滑或厚腻；中后期有少数患者出现舌绛少苔；脉象多虚弦、滑数无力或见有濡弱之脉。经用昆布、海藻、金钱草、板蓝根等加减治疗，除1例死亡外，全部治愈。据此，作者认为原方“粉”，应为米粉。}', '2024-12-16T07:22:23.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4ab5bIqHctt', 1, '{"title":"当归生姜羊肉汤","description":"<p>$u{当归}$w{三两}、$u{生姜}$w{五两}、$u{羊肉}$w{一斤}。</p>\n<p></p>\n<p>          右三味，以水八升，煮取三升，温服七合，日三眼。</p>\n<p>               寒多者加$u{生姜}$w{成一斤}；痛多而呕者，加$u{橘皮}$w{二两}、$u{白术}$w{一两}；加$u{生姜}者，亦加水五升，煮取三升二合，分温三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":211,"yaoCount":3,"drinkNum":3,"yaoList":["当归","生姜","羊肉"],"fangList":[],"fangYaoList":[{"yaoId":"JFnirDnffR9","amount":"三两","weight":null,"suffix":null,"showName":"当归","extraProcess":null},{"yaoId":"VcvhqvKkSct","amount":"五两","weight":null,"suffix":null,"showName":"生姜","extraProcess":null},{"yaoId":"FwMZI5JA24k","amount":"一斤","weight":null,"suffix":null,"showName":"羊肉","extraProcess":null}]}}', '2024-12-16T07:30:25.000Z', '2024-12-16T07:30:25.000Z', '2024-12-16T07:30:25.000Z', '$u{当归}$w{三两}、$u{生姜}$w{五两}、$u{羊肉}$w{一斤}。 右三味，以水八升，煮取三升，温服七合，日三眼。 寒多者加$u{生姜}$w{成一斤}；痛多而呕者，加$u{橘皮}$w{二两}、$u{白术}$w{一两}；加$u{生姜}者，亦加水五升，煮取三升二合，分温三服。', '2024-12-16T07:30:25.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CzPI4EWINEf', 1, '{"title":"乌头桂枝汤","description":"<p>$u{乌头}$w{五枚}。</p>\n<p></p>\n<p>         右一味，以$u{蜜}二升，煮减半，去滓，以$f{桂枝汤}$w{五合}，解之，令得一升，初服二合，不知即服三合，又不知加至五合，其知者如醉状，得吐者为中病。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":212,"yaoCount":1,"drinkNum":2,"yaoList":["乌头"],"fangList":[],"fangYaoList":[{"yaoId":"dFbCWGnQmeQ","amount":"五枚","weight":null,"suffix":null,"showName":"乌头","extraProcess":null}]}}', '2024-12-16T07:33:33.000Z', '2024-12-16T07:33:33.000Z', '2024-12-16T07:33:33.000Z', '$u{乌头}$w{五枚}。 右一味，以$u{蜜}二升，煮减半，去滓，以$f{桂枝汤}$w{五合}，解之，令得一升，初服二合，不知即服三合，又不知加至五合，其知者如醉状，得吐者为中病。', '2024-12-16T07:33:33.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lR7F7ejafip', 1, '{"title":"蜘蛛散","description":"<p>$u{蜘蛛}$w{十四枚 (熬)}、$u{桂枝}$w{一两}。</p>\n<p></p>\n<p>         右二味，为散，以白饮和服方寸匙，日再服，蜜丸亦可。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":213,"yaoCount":2,"drinkNum":2,"yaoList":["蜘蛛","桂枝"],"fangList":[],"fangYaoList":[{"yaoId":"fUxMXp8r0aZ","amount":"十四枚 (熬)","weight":null,"suffix":null,"showName":"蜘蛛","extraProcess":null},{"yaoId":"7S7n1dzieYK","amount":"一两","weight":null,"suffix":null,"showName":"桂枝","extraProcess":null}]}}', '2024-12-16T07:35:39.000Z', '2024-12-16T07:35:39.000Z', '2024-12-16T07:35:39.000Z', '$u{蜘蛛}$w{十四枚 (熬)}、$u{桂枝}$w{一两}。 右二味，为散，以白饮和服方寸匙，日再服，蜜丸亦可。', '2024-12-16T07:35:39.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ut3wSi0JpL9', 1, '{"title":"肾气丸","description":"<p>$u{地黄}$w{八两}、$u{薯蓣}$w{四两}、$u{山茱萸}$w{四两}、$u{泽泻}$w{三两}、$u{牡丹皮}$w{三两}、$u{茯苓}$w{三两}、$u{桂枝}$w{一两}、$u{附子}$w{一枚 (炮)}。</p>\n<p></p>\n<p>          右八味，末之，炼蜜和丸，如梧子大，$n{酒}下十五丸，渐加至二十五丸，日再服，白饮下亦可。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":214,"yaoCount":8,"drinkNum":15,"yaoList":["地黄","薯蓣","山茱萸","泽泻","牡丹皮","茯苓","桂枝","附子"],"fangList":[],"fangYaoList":[{"yaoId":"B2o1hdSD6X1","amount":"八两","weight":null,"suffix":null,"showName":"地黄","extraProcess":null},{"yaoId":"n7KV9vTrthx","amount":"四两","weight":null,"suffix":null,"showName":"薯蓣","extraProcess":null},{"yaoId":"ASxxg5RfLMb","amount":"四两","weight":null,"suffix":null,"showName":"山茱萸","extraProcess":null},{"yaoId":"TvTXZli2dE7","amount":"三两","weight":null,"suffix":null,"showName":"泽泻","extraProcess":null},{"yaoId":"nP2w4ZP4Yic","amount":"三两","weight":null,"suffix":null,"showName":"牡丹皮","extraProcess":null},{"yaoId":"VHE7Y68l232","amount":"三两","weight":null,"suffix":null,"showName":"茯苓","extraProcess":null},{"yaoId":"7S7n1dzieYK","amount":"一两","weight":null,"suffix":null,"showName":"桂枝","extraProcess":null},{"yaoId":"jT011T7yIVO","amount":"一枚 (炮)","weight":null,"suffix":null,"showName":"附子","extraProcess":null}]}}', '2024-12-16T07:38:13.000Z', '2024-12-16T07:38:13.000Z', '2024-12-16T07:38:13.000Z', '$u{地黄}$w{八两}、$u{薯蓣}$w{四两}、$u{山茱萸}$w{四两}、$u{泽泻}$w{三两}、$u{牡丹皮}$w{三两}、$u{茯苓}$w{三两}、$u{桂枝}$w{一两}、$u{附子}$w{一枚 (炮)}。 右八味，末之，炼蜜和丸，如梧子大，$n{酒}下十五丸，渐加至二十五丸，日再服，白饮下亦可。', '2024-12-16T07:38:13.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
