INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cvU454GYQ7k', 1, '{"title":"理中丸","description":"<p>$u{人参}$w{三两}、$u{干姜}$w{三两}、$u{甘草}$w{三两}、$u{白术}$w{三两}。</p>\n<p></p>\n<p>         右四味，捣筛，蜜和为丸，如鸡子黄大，以沸汤数合和一丸，研碎温眼，日三服，夜二服，腹中未热，可益至三四丸。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":222,"yaoCount":4,"drinkNum":5,"yaoList":["人参","干姜","甘草","白术"],"fangList":[],"fangYaoList":[{"yaoId":"GIXSHBaFv0L","amount":"三两","weight":null,"suffix":null,"showName":"人参","extraProcess":null},{"yaoId":"0p1dUWRsS6D","amount":"三两","weight":null,"suffix":null,"showName":"干姜","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":"三两","weight":null,"suffix":null,"showName":"甘草","extraProcess":null},{"yaoId":"UIYZOmiE2xW","amount":"三两","weight":null,"suffix":null,"showName":"白术","extraProcess":null}]}}', '2024-12-16T08:05:36.000Z', '2024-12-16T08:05:36.000Z', '2024-12-16T08:05:36.000Z', '$u{人参}$w{三两}、$u{干姜}$w{三两}、$u{甘草}$w{三两}、$u{白术}$w{三两}。 右四味，捣筛，蜜和为丸，如鸡子黄大，以沸汤数合和一丸，研碎温眼，日三服，夜二服，腹中未热，可益至三四丸。', '2024-12-16T08:05:36.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
