-12-16T09:03:17.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nMKe44LOWHZ', 1, '{"title":"烧裩散","description":"<p>右剪取妇人中裩，近隐处，烧灰，以水和服方寸匙，日三服，小便即利，阴头微肿则愈，妇人病取男子裩裆烧，和服如法。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":227,"yaoCount":1,"drinkNum":3,"yaoList":[],"fangList":[],"fangYaoList":[]}}', '2024-12-16T09:07:07.000Z', '2024-12-16T09:07:07.000Z', '2024-12-16T09:07:07.000Z', '右剪取妇人中裩，近隐处，烧灰，以水和服方寸匙，日三服，小便即利，阴头微肿则愈，妇人病取男子裩裆烧，和服如法。', '2024-12-16T09:07:07.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GMLlY8rqbRd', 1, '{"title":"枳实栀子豉汤","description":"<p>$u{枳实}$w{三枚（炙）}、$u{栀子}$w{十四枚（劈）}、$u{香豉}$w{一升（棉襄）}。</p>\n<p></p>\n<p>         右三味，以清浆水七升，空煮取四升，纳枳实、栀子煮取二升，纳香豉更煮五六沸，去滓，温分再服，覆令微似汗。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":228,"yaoCount":3,"drinkNum":2,"yaoList":["枳实","栀子","香豉"],"fangList":[],"fangYaoList":[{"yaoId":"FRaBwjHoVui","amount":"三枚（炙）","weight":null,"suffix":null,"showName":"枳实","extraProcess":null},{"yaoId":"7fWzC6yB6Yy","amount":"十四枚（劈）","weight":null,"suffix":null,"showName":"栀子","extraProcess":null},{"yaoId":"sx4xviDfH00","amount":"一升（棉襄）","weight":null,"suffix":null,"showName":"香豉","extraProcess":null}]}}', '2024-12-16T09:09:11.000Z', '2024-12-16T09:09:11.000Z', '2024-12-16T09:09:11.000Z', '$u{枳实}$w{三枚（炙）}、$u{栀子}$w{十四枚（劈）}、$u{香豉}$w{一升（棉襄）}。 右三味，以清浆水七升，空煮取四升，纳枳实、栀子煮取二升，纳香豉更煮五六沸，去滓，温分再服，覆令微似汗。', '2024-12-16T09:09:11.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9ucXHoAXnAl', 1, '{"title":"牡蛎泽泻散","description":"<p>$u{牡蛎}、$u{泽泻}、$u{栝蒌根}、$u{蜀漆（洗去腥）}、$u{葶历（熬）}、$u{商陆根（熬）}、$u{海藻（洗去腥）}。</p>\n<p></p>\n<p>            右七味$w{等分}，异捣，下筛为散，更入臼中治之，白饮和服方寸匙，日三服，小便利止后服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":229,"yaoCount":7,"drinkNum":3,"yaoList":["牡蛎","泽泻","栝蒌根","蜀漆（洗去腥）","葶历（熬）","商陆根（熬）","海藻（洗去腥）"],"fangList":[],"fangYaoList":[{"yaoId":"MDfiJ4S7u0U","amount":null,"weight":null,"suffix":null,"showName":"牡蛎","extraProcess":null},{"yaoId":"TvTXZli2dE7","amount":null,"weight":null,"suffix":null,"showName":"泽泻","extraProcess":null},{"yaoId":"pyZLleBsXOb","amount":null,"weight":null,"suffix":null,"showName":"栝蒌根","extraProcess":null},{"yaoId":"gFgG38KNuFm","amount":null,"weight":null,"suffix":null,"showName":"蜀漆（洗去腥）","extraProcess":null},{"yaoId":null,"amount":null,"weight":null,"suffix":null,"showName":"葶历（熬）","extraProcess":null},{"yaoId":"4W7eVdfu25M","amount":null,"weight":null,"suffix":null,"showName":"商陆根（熬）","extraProcess":null},{"yaoId":"nb7XmSpD8Iu","amount":null,"weight":null,"suffix":null,"showName":"海藻（洗去腥）","extraProcess":null}]}}', '2024-12-16T09:11:34.000Z', '2024-12-16T09:11:34.000Z', '2024-12-16T09:11:34.000Z', '$u{牡蛎}、$u{泽泻}、$u{栝蒌根}、$u{蜀漆（洗去腥）}、$u{葶历（熬）}、$u{商陆根（熬）}、$u{海藻（洗去腥）}。 右七味$w{等分}，异捣，下筛为散，更入臼中治之，白饮和服方寸匙，日三服，小便利止后服。', '2024-12-16T09:11:34.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1Qq5Th1WdLn', 1, '{"title":"百合知母汤","description":"<p>$u{百合$w{七枚}、$u{知母$w{三两}。</p>\n<p></p>\n<p>         右二味，先以水洗百合，渍一宿，当白沫出，去其水，另以泉水二升，煮取一升，去滓，别以泉水二升，煮知母取一升，去滓，后合煎取一升五合，分温再服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":230,"yaoCount":2,"drinkNum":2,"yaoList":["百合","知母"],"fangList":[],"fangYaoList":[{"yaoId":"4lJokf6uHXR","amount":"七枚","weight":null,"suffix":null,"showName":"百合","extraProcess":null},{"yaoId":"PeV28d5T6et","amount":"三两","weight":null,"suffix":null,"showName":"知母","extraProcess":null}]}}', '2024-12-16T09:16:12.000Z', '2024-12-16T09:16:12.000Z', '2024-12-16T09:16:12.000Z', '$u{百合$w{七枚}、$u{知母$w{三两}。 右二味，先以水洗百合，渍一宿，当白沫出，去其水，另以泉水二升，煮取一升，去滓，别以泉水二升，煮知母取一升，去滓，后合煎取一升五合，分温再服。', '2024-12-16T09:16:12.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('G7NoOw5KKAo', 1, '{"title":"百合滑石代赭汤","description":"<p>$u{百合}$w{七枚}、$u{滑石}$w{三两}、$u{代赭石}$w{如弹丸大 (碎棉裹)}。</p>\n<p></p>\n<p>右三味，以水先洗，煮百合如前法，别以泉水二升，煮二味，取一升，去滓，合和，重煎，取一升五合，分温再服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":231,"yaoCount":3,"drinkNum":2,"yaoList":["百合","滑石","代赭石"],"fangList":[],"fangYaoList":[{"yaoId":"4lJokf6uHXR","amount":"七枚","weight":null,"suffix":null,"showName":"百合","extraProcess":null},{"yaoId":"u6WaDjpcWhR","amount":"三两","weight":null,"suffix":null,"showName":"滑石","extraProcess":null},{"yaoId":"woIsPez0Ouc","amount":"如弹丸大 (碎棉裹)","weight":null,"suffix":null,"showName":"代赭石","extraProcess":null}]}}', '2024-12-16T09:17:42.000Z', '2024-12-16T09:17:42.000Z', '2024-12-16T09:17:42.000Z', '$u{百合}$w{七枚}、$u{滑石}$w{三两}、$u{代赭石}$w{如弹丸大 (碎棉裹)}。 右三味，以水先洗，煮百合如前法，别以泉水二升，煮二味，取一升，去滓，合和，重煎，取一升五合，分温再服。', '2024-12-16T09:17:42.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yuMpLKBECu1', 1, '{"title":"百合鸡子黄汤","description":"<p>$u{百合}$w{七枚}、$u{鸡子黄}$w{一枚}。</p>\n<p></p>\n<p>       右二味，先洗煮百合如前法，去滓，纳鸡子黄，搅匀，顿服之。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":232,"yaoCount":2,"drinkNum":2,"yaoList":["百合","鸡子黄"],"fangList":[],"fangYaoList":[{"yaoId":"4lJokf6uHXR","amount":"七枚","weight":null,"suffix":null,"showName":"百合","extraProcess":null},{"yaoId":"wDdw8s8LVWE","amount":"一枚","weight":null,"suffix":null,"showName":"鸡子黄","extraProcess":null}]}}', '2024-12-16T09:19:04.000Z', '2024-12-16T09:19:04.000Z', '2024-12-16T09:19:04.000Z', '$u{百合}$w{七枚}、$u{鸡子黄}$w{一枚}。 右二味，先洗煮百合如前法，去滓，纳鸡子黄，搅匀，顿服之。', '2024-12-16T09:19:04.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5enHhuHPh0C', 1, '{"title":"百合地黄汤","description":"<p>$u{百合}$w{七枚}、$u{地黄汁}$w{一升}。</p>\n<p></p>\n<p>        右二味，先洗煮百合如上法，去滓，纳地黄汁，煎取一升五合，分温再服，中病勿更服，大便当如漆。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":233,"yaoCount":2,"drinkNum":2,"yaoList":["百合","地黄汁"],"fangList":[],"fangYaoList":[{"yaoId":"4lJokf6uHXR","amount":"七枚","weight":null,"suffix":null,"showName":"百合","extraProcess":null},{"yaoId":null,"amount":"一升","weight":null,"suffix":null,"showName":"地黄汁","extraProcess":null}]}}', '2024-12-16T09:20:34.000Z', '2024-12-16T09:20:34.000Z', '2024-12-16T09:20:34.000Z', '$u{百合}$w{七枚}、$u{地黄汁}$w{一升}。 右二味，先洗煮百合如上法，去滓，纳地黄汁，煎取一升五合，分温再服，中病勿更服，大便当如漆。', '2024-12-16T09:20:34.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
