INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('13Fg1tvFDpF', 1, '{"title":"天雄散","description":"<p>$u{天雄}$w{三两（炮）}、$u{白术}$w{八两}、$u{桂枝}$w{六两}、$u{龙骨}$w{三两}。</p>\n<p></p>\n<p>        右四味，杵为散，酒服半钱匙，日三服，不知稍增，以知为度。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":249,"yaoCount":4,"drinkNum":3,"yaoList":["天雄","白术","桂枝","龙骨"],"fangList":[],"fangYaoList":[{"yaoId":"E5qbjuyOeWF","amount":"三两（炮）","weight":null,"suffix":null,"showName":"天雄","extraProcess":null},{"yaoId":"UIYZOmiE2xW","amount":"八两","weight":null,"suffix":null,"showName":"白术","extraProcess":null},{"yaoId":"7S7n1dzieYK","amount":"六两","weight":null,"suffix":null,"showName":"桂枝","extraProcess":null},{"yaoId":"vL3tFGA7NwL","amount":"三两","weight":null,"suffix":null,"showName":"龙骨","extraProcess":null}]}}', '2024-12-17T01:22:51.000Z', '2024-12-17T01:22:51.000Z', '2024-12-17T01:22:51.000Z', '$u{天雄}$w{三两（炮）}、$u{白术}$w{八两}、$u{桂枝}$w{六两}、$u{龙骨}$w{三两}。 右四味，杵为散，酒服半钱匙，日三服，不知稍增，以知为度。', '2024-12-17T01:22:51.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('G1C3wTP4GLE', 1, '{"title":"黄芪建中汤","description":"<p>$u{桂枝}$w{三两}、$u{芍药}$w{六两}、$u{甘草}$w{二两 (炙)}、$u{生姜}$w{三两（切）}、$u{大枣}$w{十二枚（劈）}、$u{胶饴}$w{一升}}、$u{黄芪}$w{一两半}。</p>\n<p></p>\n<p>      右七味，以水七升，煮取三升，去滓，内胶饴，更上微火消解，温服一升，日三服。</p>\n<p></p>\n<p>     气短，胸满者，加生姜一两；</p>\n<p>     腹满者，去大枣，加茯苓一两半；</p>\n<p>     大便秘结者，去大枣，加枳实一两半；</p>\n<p>     肺气虚损者，加半夏三两。</p>\n<p></p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":250,"yaoCount":7,"drinkNum":3,"yaoList":["桂枝","芍药","甘草","生姜","大枣","胶饴","黄芪"],"fangList":[],"fangYaoList":[{"yaoId":"7S7n1dzieYK","amount":"三两","weight":null,"suffix":null,"showName":"桂枝","extraProcess":null},{"yaoId":"Ro0664U6sTQ","amount":"六两","weight":null,"suffix":null,"showName":"芍药","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":"二两 (炙)","weight":null,"suffix":null,"showName":"甘草","extraProcess":null},{"yaoId":"VcvhqvKkSct","amount":"三两（切）","weight":null,"suffix":null,"showName":"生姜","extraProcess":null},{"yaoId":"JZ9gTmGblYB","amount":"十二枚（劈）","weight":null,"suffix":null,"showName":"大枣","extraProcess":null},{"yaoId":"q7UHJJ3ORHQ","amount":"一升","weight":null,"suffix":null,"showName":"胶饴","extraProcess":null},{"yaoId":"i7j1zMcc48a","amount":"一两半","weight":null,"suffix":null,"showName":"黄芪","extraProcess":null}]}}', '2024-12-17T01:59:47.000Z', '2024-12-17T01:59:47.000Z', '2024-12-17T01:59:47.000Z', '$u{桂枝}$w{三两}、$u{芍药}$w{六两}、$u{甘草}$w{二两 (炙)}、$u{生姜}$w{三两（切）}、$u{大枣}$w{十二枚（劈）}、$u{胶饴}$w{一升}}、$u{黄芪}$w{一两半}。 右七味，以水七升，煮取三升，去滓，内胶饴，更上微火消解，温服一升，日三服。 气短，胸满者，加生姜一两； 腹满者，去大枣，加茯苓一两半； 大便秘结者，去大枣，加枳实一两半； 肺气虚损者，加半夏三两。', '2024-12-17T01:59:47.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wsRBoOAi1iG', 1, '{"title":"蛇床子散","description":"<p>$u{蛇床子}$w{一两}。</p>\n<p></p>\n<p>         右一味，末之，以白粉少许，和合相得，如枣大，棉裹纳阴中，自温。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":251,"yaoCount":1,"drinkNum":1,"yaoList":["蛇床子"],"fangList":[],"fangYaoList":[{"yaoId":"lMDTFwL4kfg","amount":"一两","weight":null,"suffix":null,"showName":"蛇床子","extraProcess":null}]}}', '2024-12-17T02:01:41.000Z', '2024-12-17T02:01:41.000Z', '2024-12-17T02:01:41.000Z', '$u{蛇床子}$w{一两}。 右一味，末之，以白粉少许，和合相得，如枣大，棉裹纳阴中，自温。', '2024-12-17T02:01:41.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SPLgKjY4sXs', 1, '{"title":"酸枣仁汤","description":"<p>$u{酸枣仁}$w{二升}、$u{甘草}$w{一两}、$u{知母}$w{二两}、$u{茯苓}$w{二两}、$u{川芎}$w{一两}。</p>\n<p></p>\n<p>       右五味，以水八升，煮酸枣仁，得六升，纳诸药，煮取三升，去滓，温服一升，日三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":252,"yaoCount":5,"drinkNum":3,"yaoList":["酸枣仁","甘草","知母","茯苓","川芎"],"fangList":[],"fangYaoList":[{"yaoId":"ODZGxGssDUt","amount":"二升","weight":null,"suffix":null,"showName":"酸枣仁","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":"一两","weight":null,"suffix":null,"showName":"甘草","extraProcess":null},{"yaoId":"PeV28d5T6et","amount":"二两","weight":null,"suffix":null,"showName":"知母","extraProcess":null},{"yaoId":"VHE7Y68l232","amount":"二两","weight":null,"suffix":null,"showName":"茯苓","extraProcess":null},{"yaoId":null,"amount":"一两","weight":null,"suffix":null,"showName":"川芎","extraProcess":null}]}}', '2024-12-17T02:04:45.000Z', '2024-12-17T02:04:45.000Z', '2024-12-17T02:04:45.000Z', '$u{酸枣仁}$w{二升}、$u{甘草}$w{一两}、$u{知母}$w{二两}、$u{茯苓}$w{二两}、$u{川芎}$w{一两}。 右五味，以水八升，煮酸枣仁，得六升，纳诸药，煮取三升，去滓，温服一升，日三服。', '2024-12-17T02:04:45.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3IZ1cChW1vR', 1, '{"title":"大黄䗪虫丸","description":"<p>$u{大黄}$w{十两}、$u{黄芩}$w{二两}、$u{甘草}$w{三两}、$u{桃仁}$w{一升}、$u{杏仁}$w{一升}、$u{芍药}$w{四两}、$u{地黄}$w{十两}、$u{干漆}$w{一两}、$u{虻虫}$w{一升}、$u{水蛭}$w{百枚}、$u{蛴螬}$w{一升}、$u{䗪虫}$w{半升}</p>\n<p></p>\n<p>           右十二味，末之，炼蜜和丸，如小豆大，酒饮服五丸，日三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":253,"yaoCount":12,"drinkNum":3,"yaoList":["大黄","黄芩","甘草","桃仁","杏仁","芍药","地黄","干漆","虻虫","水蛭","蛴螬","䗪虫"],"fangList":[],"fangYaoList":[{"yaoId":"To31b37bc6Z","amount":"十两","weight":null,"suffix":null,"showName":"大黄","extraProcess":null},{"yaoId":"fd3riAoOlLa","amount":"二两","weight":null,"suffix":null,"showName":"黄芩","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":"三两","weight":null,"suffix":null,"showName":"甘草","extraProcess":null},{"yaoId":"k2cI79Wat6h","amount":"一升","weight":null,"suffix":null,"showName":"桃仁","extraProcess":null},{"yaoId":"Hs7PKqMqKRj","amount":"一升","weight":null,"suffix":null,"showName":"杏仁","extraProcess":null},{"yaoId":"Ro0664U6sTQ","amount":"四两","weight":null,"suffix":null,"showName":"芍药","extraProcess":null},{"yaoId":"B2o1hdSD6X1","amount":"十两","weight":null,"suffix":null,"showName":"地黄","extraProcess":null},{"yaoId":"41gTtXf6W3Z","amount":"一两","weight":null,"suffix":null,"showName":"干漆","extraProcess":null},{"yaoId":"L1yNgzB2bxB","amount":"一升","weight":null,"suffix":null,"showName":"虻虫","extraProcess":null},{"yaoId":"biroLUs3POn","amount":"百枚","weight":null,"suffix":null,"showName":"水蛭","extraProcess":null},{"yaoId":"97tN0MlutoJ","amount":"一升","weight":null,"suffix":null,"showName":"蛴螬","extraProcess":null},{"yaoId":"nMnl8EhuWTn","amount":"半升","weight":null,"suffix":null,"showName":"䗪虫","extraProcess":null}]}}', '2024-12-17T02:09:25.000Z', '2024-12-17T02:09:25.000Z', '2024-12-17T02:09:25.000Z', '$u{大黄}$w{十两}、$u{黄芩}$w{二两}、$u{甘草}$w{三两}、$u{桃仁}$w{一升}、$u{杏仁}$w{一升}、$u{芍药}$w{四两}、$u{地黄}$w{十两}、$u{干漆}$w{一两}、$u{虻虫}$w{一升}、$u{水蛭}$w{百枚}、$u{蛴螬}$w{一升}、$u{䗪虫}$w{半升} 右十二味，末之，炼蜜和丸，如小豆大，酒饮服五丸，日三服。', '2024-12-17T02:09:25.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('m9pZu2RoSTL', 1, '{"title":"硝石矾石散","description":"<p>$u{硝石（熬黄）}、$u{矾石（烧）}$w{各等分}。</p>\n<p></p>\n<p>       右二味，为散，大麦粥汁和服方寸匙，日三服，大便黑，小便黄，是其候也。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":254,"yaoCount":2,"drinkNum":3,"yaoList":["硝石（熬黄）","矾石（烧）"],"fangList":[],"fangYaoList":[{"yaoId":"VbIDIYURZdR","amount":null,"weight":null,"suffix":null,"showName":"硝石（熬黄）","extraProcess":null},{"yaoId":"ozDrmO1Ighz","amount":"各等分","weight":null,"suffix":null,"showName":"矾石（烧）","extraProcess":null}]}}', '2024-12-17T02:12:49.000Z', '2024-12-17T02:12:49.000Z', '2024-12-17T02:12:49.000Z', '$u{硝石（熬黄）}、$u{矾石（烧）}$w{各等分}。 右二味，为散，大麦粥汁和服方寸匙，日三服，大便黑，小便黄，是其候也。', '2024-12-17T02:12:49.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BbvxRdySk2R', 1, '{"title":"十枣汤","description":"<p>$u{芜花 (熬)}、$u{甘遂}、$u{大戟}$w{各等分}。</p>\n<p>右三味，捣筛，以水一升五合，先煮肥大枣十枚，取八合，去滓，纳药末，强人服一钱匙，赢人服半钱匙，平旦温服之，不下，明日更加半钱，得快利后，糜粥自养。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":255,"yaoCount":3,"drinkNum":1,"yaoList":["芜花 (熬)","甘遂","大戟"],"fangList":[],"fangYaoList":[{"yaoId":null,"amount":null,"weight":null,"suffix":null,"showName":"芜花 (熬)","extraProcess":null},{"yaoId":"7nTRDUdzsoW","amount":null,"weight":null,"suffix":null,"showName":"甘遂","extraProcess":null},{"yaoId":"gZLQX87OyZG","amount":"各等分","weight":null,"suffix":null,"showName":"大戟","extraProcess":null}]}}', '2024-12-17T02:27:14.000Z', '2024-12-17T02:27:14.000Z', '2024-12-17T02:27:14.000Z', '$u{芜花 (熬)}、$u{甘遂}、$u{大戟}$w{各等分}。 右三味，捣筛，以水一升五合，先煮肥大枣十枚，取八合，去滓，纳药末，强人服一钱匙，赢人服半钱匙，平旦温服之，不下，明日更加半钱，得快利后，糜粥自养。', '2024-12-17T02:27:14.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pKLB2KA3V7g', 1, '{"title":"射干麻黄汤","description":"<p>$u{射干}$w{三两}、$u{麻黄}$w{三两}、$u{半夏}$w{半升}、$u{五味子}$w{半升}、$u{生姜}$w{四两}、$u{细辛}$w{三两}、$u{大枣}$w{七枚}。</p>\n<p></p>\n<p>          右七味，以水一斗二升，先煮麻黄，去上沫，纳诸药，煮取三升，分温三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":256,"yaoCount":7,"drinkNum":3,"yaoList":["射干","麻黄","半夏","五味子","生姜","细辛","大枣"],"fangList":[],"fangYaoList":[{"yaoId":"PEcY2j6wjoH","amount":"三两","weight":null,"suffix":null,"showName":"射干","extraProcess":null},{"yaoId":"nxz0hvgpJJf","amount":"三两","weight":null,"suffix":null,"showName":"麻黄","extraProcess":null},{"yaoId":"axI8tfBmKAx","amount":"半升","weight":null,"suffix":null,"showName":"半夏","extraProcess":null},{"yaoId":"C74sm5pJRdN","amount":"半升","weight":null,"suffix":null,"showName":"五味子","extraProcess":null},{"yaoId":"VcvhqvKkSct","amount":"四两","weight":null,"suffix":null,"showName":"生姜","extraProcess":null},{"yaoId":"MCBshcFNHhk","amount":"三两","weight":null,"suffix":null,"showName":"细辛","extraProcess":null},{"yaoId":"JZ9gTmGblYB","amount":"七枚","weight":null,"suffix":null,"showName":"大枣","extraProcess":null}]}}', '2024-12-17T02:28:53.000Z', '2024-12-17T02:28:53.000Z', '2024-12-17T02:28:53.000Z', '$u{射干}$w{三两}、$u{麻黄}$w{三两}、$u{半夏}$w{半升}、$u{五味子}$w{半升}、$u{生姜}$w{四两}、$u{细辛}$w{三两}、$u{大枣}$w{七枚}。 右七味，以水一斗二升，先煮麻黄，去上沫，纳诸药，煮取三升，分温三服。', '2024-12-17T02:28:53.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('j5Cc8N2QtXm', 1, '{"title":"皂荚丸","description":"<p>$u{皂荚}$w{八两 (刮去皮酥炙)}。</p>\n<p>右一味，末之，蜜丸如梧桐子大，以枣膏和汤，服三丸，日三服，夜一服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":257,"yaoCount":1,"drinkNum":4,"yaoList":["皂荚"],"fangList":[],"fangYaoList":[{"yaoId":"hmJnKWK15KJ","amount":"八两 (刮去皮酥炙)","weight":null,"suffix":null,"showName":"皂荚","extraProcess":null}]}}', '2024-12-17T02:30:21.000Z', '2024-12-17T02:30:21.000Z', '2024-12-17T02:30:21.000Z', '$u{皂荚}$w{八两 (刮去皮酥炙)}。 右一味，末之，蜜丸如梧桐子大，以枣膏和汤，服三丸，日三服，夜一服。', '2024-12-17T02:30:21.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
