INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3CsNbkETv1J', 1, '{"title":"葶苈大枣泻肺汤","description":"<p>$u{葶苈}$w{ (熬令黄色捣丸如弹子大)}、$u{大枣}$w{十二枚}。</p>\n<p></p>\n<p>     右二味，以水三升，先煮大枣取二升，去枣，纳葶苈，煮取一升，去滓，顿服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":263,"yaoCount":2,"drinkNum":2,"yaoList":["葶苈","大枣"],"fangList":[],"fangYaoList":[{"yaoId":null,"amount":"(熬令黄色捣丸如弹子大)","weight":null,"suffix":null,"showName":"葶苈","extraProcess":null},{"yaoId":"JZ9gTmGblYB","amount":"十二枚","weight":null,"suffix":null,"showName":"大枣","extraProcess":null}]}}', '2024-12-17T02:45:18.000Z', '2024-12-17T02:45:18.000Z', '2024-12-17T02:45:18.000Z', '$u{葶苈}$w{ (熬令黄色捣丸如弹子大)}、$u{大枣}$w{十二枚}。 右二味，以水三升，先煮大枣取二升，去枣，纳葶苈，煮取一升，去滓，顿服。', '2024-12-17T02:45:18.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TOaPPcq5qAw', 1, '{"title":"甘遂半夏汤","description":"<p>$u{甘遂}$w{大者三枚}、$u{半夏}$w{十二枚}、$u{芍药}$w{五枚}、$u{甘草}$w{如指大一枚 (炙)}。</p>\n<p></p>\n<p>         右四味，以水二升，煮取半升，去滓，以蜜半升和药汁，煎取八合，顿服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":264,"yaoCount":4,"drinkNum":2,"yaoList":["甘遂","半夏","芍药","甘草"],"fangList":[],"fangYaoList":[{"yaoId":"7nTRDUdzsoW","amount":"大者三枚","weight":null,"suffix":null,"showName":"甘遂","extraProcess":null},{"yaoId":"axI8tfBmKAx","amount":"十二枚","weight":null,"suffix":null,"showName":"半夏","extraProcess":null},{"yaoId":"Ro0664U6sTQ","amount":"五枚","weight":null,"suffix":null,"showName":"芍药","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":"如指大一枚 (炙)","weight":null,"suffix":null,"showName":"甘草","extraProcess":null}]}}', '2024-12-17T02:54:54.000Z', '2024-12-17T02:54:54.000Z', '2024-12-17T02:54:54.000Z', '$u{甘遂}$w{大者三枚}、$u{半夏}$w{十二枚}、$u{芍药}$w{五枚}、$u{甘草}$w{如指大一枚 (炙)}。 右四味，以水二升，煮取半升，去滓，以蜜半升和药汁，煎取八合，顿服。', '2024-12-17T02:54:54.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('M1o2mB67vL3', 1, '{"title":"木防已汤","description":"<p>$u{木防已}$w{三两}、$u{石膏}$w{鸡子大十二枚}、$u{桂枝}$w{二两}、$u{人参}$w{四两}。</p>\n<p> </p>\n<p>       右四味，以水六升，煮取二升，去滓，分温再服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":265,"yaoCount":4,"drinkNum":2,"yaoList":["木防已","石膏","桂枝","人参"],"fangList":[],"fangYaoList":[{"yaoId":null,"amount":"三两","weight":null,"suffix":null,"showName":"木防已","extraProcess":null},{"yaoId":"S7mhkBtEhPL","amount":"鸡子大十二枚","weight":null,"suffix":null,"showName":"石膏","extraProcess":null},{"yaoId":"7S7n1dzieYK","amount":"二两","weight":null,"suffix":null,"showName":"桂枝","extraProcess":null},{"yaoId":"GIXSHBaFv0L","amount":"四两","weight":null,"suffix":null,"showName":"人参","extraProcess":null}]}}', '2024-12-17T02:59:57.000Z', '2024-12-17T02:59:57.000Z', '2024-12-17T02:59:57.000Z', '$u{木防已}$w{三两}、$u{石膏}$w{鸡子大十二枚}、$u{桂枝}$w{二两}、$u{人参}$w{四两}。 右四味，以水六升，煮取二升，去滓，分温再服。', '2024-12-17T02:59:57.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Z8auIJqnENI', 1, '{"title":"木防已去石膏加茯苓芒硝汤","description":"<p>$u{木防已}$w{二两}、$u{桂枝}$w{二两}、$u{茯苓}$w{四两}、$u{人参}$w{四两}、$u{芒硝}$w{三合}。</p>\n<p></p>\n<p>           右四味，以水六升，煮取二升，去滓，纳芒硝，再微煎，分温再服，微利则愈。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":266,"yaoCount":4,"drinkNum":2,"yaoList":["木防已","桂枝","茯苓","人参","芒硝"],"fangList":[],"fangYaoList":[{"yaoId":null,"amount":"二两","weight":null,"suffix":null,"showName":"木防已","extraProcess":null},{"yaoId":"7S7n1dzieYK","amount":"二两","weight":null,"suffix":null,"showName":"桂枝","extraProcess":null},{"yaoId":"VHE7Y68l232","amount":"四两","weight":null,"suffix":null,"showName":"茯苓","extraProcess":null},{"yaoId":"GIXSHBaFv0L","amount":"四两","weight":null,"suffix":null,"showName":"人参","extraProcess":null},{"yaoId":"J7mL6gla0C0","amount":"三合","weight":null,"suffix":null,"showName":"芒硝","extraProcess":null}]}}', '2024-12-17T03:01:10.000Z', '2024-12-17T03:01:10.000Z', '2024-12-17T03:01:10.000Z', '$u{木防已}$w{二两}、$u{桂枝}$w{二两}、$u{茯苓}$w{四两}、$u{人参}$w{四两}、$u{芒硝}$w{三合}。 右四味，以水六升，煮取二升，去滓，纳芒硝，再微煎，分温再服，微利则愈。', '2024-12-17T03:01:10.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zZNCYC51TC4', 1, '{"title":"泽泻汤","description":"<p>$u{泽泻}$w{五两}、$u{白术}$w{二两}。</p>\n<p></p>\n<p>        右二味，以水二升，煮取一升，分温再服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":267,"yaoCount":2,"drinkNum":2,"yaoList":["泽泻","白术"],"fangList":[],"fangYaoList":[{"yaoId":"TvTXZli2dE7","amount":"五两","weight":null,"suffix":null,"showName":"泽泻","extraProcess":null},{"yaoId":"UIYZOmiE2xW","amount":"二两","weight":null,"suffix":null,"showName":"白术","extraProcess":null}]}}', '2024-12-17T03:03:05.000Z', '2024-12-17T03:03:05.000Z', '2024-12-17T03:03:05.000Z', '$u{泽泻}$w{五两}、$u{白术}$w{二两}。 右二味，以水二升，煮取一升，分温再服。', '2024-12-17T03:03:05.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
