INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('raMwobKsCYq', 1, '{"title":"防已椒目葶苈大黄丸","description":"<p>$u{防已}、$u{椒目}、$u{葶苈}、$u{大黄}$w{各一两}。</p>\n<p></p>\n<p>       右四味，捣筛，炼蜜为丸，如梧桐子大，先食，饮服一丸，日三服，不知稍增。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":269,"yaoCount":4,"drinkNum":3,"yaoList":["防已","椒目","葶苈","大黄"],"fangList":[],"fangYaoList":[{"yaoId":null,"amount":null,"weight":null,"suffix":null,"showName":"防已","extraProcess":null},{"yaoId":"EQ39pyP4gYo","amount":null,"weight":null,"suffix":null,"showName":"椒目","extraProcess":null},{"yaoId":null,"amount":null,"weight":null,"suffix":null,"showName":"葶苈","extraProcess":null},{"yaoId":"To31b37bc6Z","amount":"各一两","weight":null,"suffix":null,"showName":"大黄","extraProcess":null}]}}', '2024-12-17T03:07:17.000Z', '2024-12-17T03:07:17.000Z', '2024-12-17T03:07:17.000Z', '$u{防已}、$u{椒目}、$u{葶苈}、$u{大黄}$w{各一两}。 右四味，捣筛，炼蜜为丸，如梧桐子大，先食，饮服一丸，日三服，不知稍增。', '2024-12-17T03:07:17.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jEobR6tneGA', 1, '{"title":"小半夏加茯苓汤","description":"<p>$u{半夏}$w{一升}、$u{生姜}$w{半斤}、$u{茯苓}$w{四两}。</p>\n<p></p>\n<p>      右三味，以水七升，煮取二升，去滓，分温再服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":270,"yaoCount":3,"drinkNum":2,"yaoList":["半夏","生姜","茯苓"],"fangList":[],"fangYaoList":[{"yaoId":"axI8tfBmKAx","amount":"一升","weight":null,"suffix":null,"showName":"半夏","extraProcess":null},{"yaoId":"VcvhqvKkSct","amount":"半斤","weight":null,"suffix":null,"showName":"生姜","extraProcess":null},{"yaoId":"VHE7Y68l232","amount":"四两","weight":null,"suffix":null,"showName":"茯苓","extraProcess":null}]}}', '2024-12-17T03:10:06.000Z', '2024-12-17T03:10:06.000Z', '2024-12-17T03:10:06.000Z', '$u{半夏}$w{一升}、$u{生姜}$w{半斤}、$u{茯苓}$w{四两}。 右三味，以水七升，煮取二升，去滓，分温再服。', '2024-12-17T03:10:06.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('q0MmSlVqEHl', 1, '{"title":"防已黄芪汤","description":"<p>$u{防已}$w{一两}、$u{甘草}$w{五钱 (炙)}、$u{白术}$w{七钱半}、$u{黄芪}$w{一两}。</p>\n<p></p>\n<p>       右四味，剉如麻豆大，每抄五钱匙，$u{生姜}$w{四片}、$u{大枣}$w{一枚}、水一升半，煮取八合，去滓，温服；</p>\n<p>   </p>\n<p>      喘者，加$u{麻黄}$w{五钱}，</p>\n<p>      胃中不和者，加$u{芍药}$w{三分}；</p>\n<p>      气上冲者，加$u{桂枝}$w{三分}；</p>\n<p>     下有陈寒者，加$u{细辛}$w{三分}；服后当如虫行皮中，从腰下如冰，后坐被上，又以一被绕腰下，温令有微汗差。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":271,"yaoCount":6,"drinkNum":1,"yaoList":["防已","甘草","白术","黄芪"],"fangList":[],"fangYaoList":[{"yaoId":null,"amount":"一两","weight":null,"suffix":null,"showName":"防已","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":"五钱 (炙)","weight":null,"suffix":null,"showName":"甘草","extraProcess":null},{"yaoId":"UIYZOmiE2xW","amount":"七钱半","weight":null,"suffix":null,"showName":"白术","extraProcess":null},{"yaoId":"i7j1zMcc48a","amount":"一两","weight":null,"suffix":null,"showName":"黄芪","extraProcess":null}]}}', '2024-12-17T03:37:57.000Z', '2024-12-17T03:37:57.000Z', '2024-12-17T03:37:57.000Z', '$u{防已}$w{一两}、$u{甘草}$w{五钱 (炙)}、$u{白术}$w{七钱半}、$u{黄芪}$w{一两}。 右四味，剉如麻豆大，每抄五钱匙，$u{生姜}$w{四片}、$u{大枣}$w{一枚}、水一升半，煮取八合，去滓，温服； 喘者，加$u{麻黄}$w{五钱}， 胃中不和者，加$u{芍药}$w{三分}； 气上冲者，加$u{桂枝}$w{三分}； 下有陈寒者，加$u{细辛}$w{三分}；服后当如虫行皮中，从腰下如冰，后坐被上，又以一被绕腰下，温令有微汗差。', '2024-12-17T03:37:57.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gEQZEtp6zlL', 1, '{"title":"越婢汤","description":"<p>$u{麻黄}$w{六两}、$u{石膏}$w{半斤}、$u{甘草}$w{二两}、$u{生姜}$w{三两}、$u{大枣}$w{十二枚}。</p>\n<p></p>\n<p>       右五味，以水六升，先煮麻黄，去上沫，纳诸药，煮取三升，去滓，分温三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":272,"yaoCount":5,"drinkNum":3,"yaoList":["麻黄","石膏","甘草","生姜","大枣"],"fangList":[],"fangYaoList":[{"yaoId":"nxz0hvgpJJf","amount":"六两","weight":null,"suffix":null,"showName":"麻黄","extraProcess":null},{"yaoId":"S7mhkBtEhPL","amount":"半斤","weight":null,"suffix":null,"showName":"石膏","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":"二两","weight":null,"suffix":null,"showName":"甘草","extraProcess":null},{"yaoId":"VcvhqvKkSct","amount":"三两","weight":null,"suffix":null,"showName":"生姜","extraProcess":null},{"yaoId":"JZ9gTmGblYB","amount":"十二枚","weight":null,"suffix":null,"showName":"大枣","extraProcess":null}]}}', '2024-12-17T03:40:08.000Z', '2024-12-17T03:40:08.000Z', '2024-12-17T03:40:08.000Z', '$u{麻黄}$w{六两}、$u{石膏}$w{半斤}、$u{甘草}$w{二两}、$u{生姜}$w{三两}、$u{大枣}$w{十二枚}。 右五味，以水六升，先煮麻黄，去上沫，纳诸药，煮取三升，去滓，分温三服。', '2024-12-17T03:40:08.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6GBl97lnjWV', 1, '{"title":"防已茯苓汤","description":"<p>$u{防已}$w{三两}、$u{黄芪}$w{三两}、$u{桂枝}$w{三两}、$u{茯苓}$w{六两}、$u{甘草}$w{二两 (炙)}。</p>\n<p></p>\n<p>       右五味，以水六升，煮取三升，分温三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":273,"yaoCount":5,"drinkNum":3,"yaoList":["防已","黄芪","桂枝","茯苓","甘草"],"fangList":[],"fangYaoList":[{"yaoId":null,"amount":"三两","weight":null,"suffix":null,"showName":"防已","extraProcess":null},{"yaoId":"i7j1zMcc48a","amount":"三两","weight":null,"suffix":null,"showName":"黄芪","extraProcess":null},{"yaoId":"7S7n1dzieYK","amount":"三两","weight":null,"suffix":null,"showName":"桂枝","extraProcess":null},{"yaoId":"VHE7Y68l232","amount":"六两","weight":null,"suffix":null,"showName":"茯苓","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":"二两 (炙)","weight":null,"suffix":null,"showName":"甘草","extraProcess":null}]}}', '2024-12-17T03:42:40.000Z', '2024-12-17T03:42:40.000Z', '2024-12-17T03:42:40.000Z', '$u{防已}$w{三两}、$u{黄芪}$w{三两}、$u{桂枝}$w{三两}、$u{茯苓}$w{六两}、$u{甘草}$w{二两 (炙)}。 右五味，以水六升，煮取三升，分温三服。', '2024-12-17T03:42:40.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Bv6n8FmWxO9', 1, '{"title":"甘草麻黄汤","description":"<p>甘草二两、麻黄四两。</p>\n<p></p>\n<p>    右二味，以水五升，先煮麻黄，去上沫，纳甘草，煮取三升，去滓，温服一升，复令汗出，不汗再服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":274,"yaoCount":2,"drinkNum":3,"yaoList":[],"fangList":[],"fangYaoList":[]}}', '2024-12-17T03:51:28.000Z', '2024-12-17T03:51:28.000Z', '2024-12-17T03:51:28.000Z', '甘草二两、麻黄四两。 右二味，以水五升，先煮麻黄，去上沫，纳甘草，煮取三升，去滓，温服一升，复令汗出，不汗再服。', '2024-12-17T03:51:28.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('w1oskdkthQ5', 1, '{"title":"越婢加术汤","description":"<p>$u{麻黄}$w{六两}、$u{石膏}$w{半斤}、$u{甘草}$w{二两 (炙)}、$u{生姜}$w{三两}、$u{大枣}$w{十五枚}、$u{白术}$w{四两}。</p>\n<p></p>\n<p>         右六味，以水六升，先煮麻黄，去上沫，纳诸药，煮取三升，分温三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":275,"yaoCount":6,"drinkNum":3,"yaoList":["麻黄","石膏","甘草","生姜","大枣","白术"],"fangList":[],"fangYaoList":[{"yaoId":"nxz0hvgpJJf","amount":"六两","weight":null,"suffix":null,"showName":"麻黄","extraProcess":null},{"yaoId":"S7mhkBtEhPL","amount":"半斤","weight":null,"suffix":null,"showName":"石膏","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":"二两 (炙)","weight":null,"suffix":null,"showName":"甘草","extraProcess":null},{"yaoId":"VcvhqvKkSct","amount":"三两","weight":null,"suffix":null,"showName":"生姜","extraProcess":null},{"yaoId":"JZ9gTmGblYB","amount":"十五枚","weight":null,"suffix":null,"showName":"大枣","extraProcess":null},{"yaoId":"UIYZOmiE2xW","amount":"四两","weight":null,"suffix":null,"showName":"白术","extraProcess":null}]}}', '2024-12-17T03:53:09.000Z', '2024-12-17T03:53:09.000Z', '2024-12-17T03:53:09.000Z', '$u{麻黄}$w{六两}、$u{石膏}$w{半斤}、$u{甘草}$w{二两 (炙)}、$u{生姜}$w{三两}、$u{大枣}$w{十五枚}、$u{白术}$w{四两}。 右六味，以水六升，先煮麻黄，去上沫，纳诸药，煮取三升，分温三服。', '2024-12-17T03:53:09.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fWF0GmAj2KN', 1, '{"title":"黄芪芍药桂枝汤","description":"<p>$u{黄芪}$w{五两}、$u{芍药}$w{三两}、$u{桂枝}$w{三两}。</p>\n<p></p>\n<p>       右三味，以$u{苦酒}$w{一升}，水七升，相合，煮取三升，去滓，温服一升，当心烦，服至六七日乃解；若心烦不止者，以苦酒阻故也，以美酒醢易之。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":276,"yaoCount":4,"drinkNum":3,"yaoList":["黄芪","芍药","桂枝"],"fangList":[],"fangYaoList":[{"yaoId":"i7j1zMcc48a","amount":"五两","weight":null,"suffix":null,"showName":"黄芪","extraProcess":null},{"yaoId":"Ro0664U6sTQ","amount":"三两","weight":null,"suffix":null,"showName":"芍药","extraProcess":null},{"yaoId":"7S7n1dzieYK","amount":"三两","weight":null,"suffix":null,"showName":"桂枝","extraProcess":null}]}}', '2024-12-17T03:55:18.000Z', '2024-12-17T03:55:18.000Z', '2024-12-17T03:55:18.000Z', '$u{黄芪}$w{五两}、$u{芍药}$w{三两}、$u{桂枝}$w{三两}。 右三味，以$u{苦酒}$w{一升}，水七升，相合，煮取三升，去滓，温服一升，当心烦，服至六七日乃解；若心烦不止者，以苦酒阻故也，以美酒醢易之。', '2024-12-17T03:55:18.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
