INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IaDLYkqlY9l', 1, '{"title":"括蒌瞿麦薯蓣丸","description":"<p>$u{括蒌根}$w{二两}、$u{瞿麦}$w{一两}、$u{薯蓣}$w{二两}、$u{附子}$w{一枚 (炮)}、$u{茯苓}$w{三两}。</p>\n<p></p>\n<p>           右五味，末之，炼蜜为丸，如梧桐子大，饮服二丸，日三服，不知可增至七八丸，以小便利，腹中温为知。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":282,"yaoCount":5,"drinkNum":3,"yaoList":["括蒌根","瞿麦","薯蓣","附子","茯苓"],"fangList":[],"fangYaoList":[{"yaoId":"pyZLleBsXOb","amount":"二两","weight":null,"suffix":null,"showName":"括蒌根","extraProcess":null},{"yaoId":"Ug7wsIcyGqw","amount":"一两","weight":null,"suffix":null,"showName":"瞿麦","extraProcess":null},{"yaoId":"n7KV9vTrthx","amount":"二两","weight":null,"suffix":null,"showName":"薯蓣","extraProcess":null},{"yaoId":"jT011T7yIVO","amount":"一枚 (炮)","weight":null,"suffix":null,"showName":"附子","extraProcess":null},{"yaoId":"VHE7Y68l232","amount":"三两","weight":null,"suffix":null,"showName":"茯苓","extraProcess":null}]}}', '2024-12-17T06:47:11.000Z', '2024-12-17T06:47:11.000Z', '2024-12-17T06:47:11.000Z', '$u{括蒌根}$w{二两}、$u{瞿麦}$w{一两}、$u{薯蓣}$w{二两}、$u{附子}$w{一枚 (炮)}、$u{茯苓}$w{三两}。 右五味，末之，炼蜜为丸，如梧桐子大，饮服二丸，日三服，不知可增至七八丸，以小便利，腹中温为知。', '2024-12-17T06:47:11.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1jbaQOD1cd0', 1, '{"title":"茯苓白术戎盐汤","description":"<p>$u{滑石}$w{一斤}、$u{乱发}$w{一斤 (烧)}、$u{白鱼}$w{一斤}。</p>\n<p></p>\n<p>       右三味杵为散，饮服方寸匙，日三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":283,"yaoCount":3,"drinkNum":3,"yaoList":["滑石","乱发","白鱼"],"fangList":[],"fangYaoList":[{"yaoId":"u6WaDjpcWhR","amount":"一斤","weight":null,"suffix":null,"showName":"滑石","extraProcess":null},{"yaoId":"fmrz9cHIBuv","amount":"一斤 (烧)","weight":null,"suffix":null,"showName":"乱发","extraProcess":null},{"yaoId":"1lOZZk4edSX","amount":"一斤","weight":null,"suffix":null,"showName":"白鱼","extraProcess":null}]}}', '2024-12-17T06:50:14.000Z', '2024-12-17T06:50:14.000Z', '2024-12-17T06:50:14.000Z', '$u{滑石}$w{一斤}、$u{乱发}$w{一斤 (烧)}、$u{白鱼}$w{一斤}。 右三味杵为散，饮服方寸匙，日三服。', '2024-12-17T06:50:14.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SlO0jRYRqRA', 1, '{"title":"茯苓白术戎盐汤","description":"<p>$u{茯苓}$w{半斤}、$u{白术}$w{二两}、$u{戎盐}$w{二枚 (弹丸大)}。</p>\n<p></p>\n<p>        右三味，先以水一斗，煮二味，取三升，去滓，纳戎盐，更上微火一二沸化之，分温三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":284,"yaoCount":3,"drinkNum":3,"yaoList":["茯苓","白术","戎盐"],"fangList":[],"fangYaoList":[{"yaoId":"VHE7Y68l232","amount":"半斤","weight":null,"suffix":null,"showName":"茯苓","extraProcess":null},{"yaoId":"UIYZOmiE2xW","amount":"二两","weight":null,"suffix":null,"showName":"白术","extraProcess":null},{"yaoId":"Aj1WLaM2FzC","amount":"二枚 (弹丸大)","weight":null,"suffix":null,"showName":"戎盐","extraProcess":null}]}}', '2024-12-17T06:51:32.000Z', '2024-12-17T06:51:32.000Z', '2024-12-17T06:51:32.000Z', '$u{茯苓}$w{半斤}、$u{白术}$w{二两}、$u{戎盐}$w{二枚 (弹丸大)}。 右三味，先以水一斗，煮二味，取三升，去滓，纳戎盐，更上微火一二沸化之，分温三服。', '2024-12-17T06:51:32.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('z8rhE7nBfGO', 1, '{"title":"下瘀血汤","description":"<p>$u{大黄}$w{三两}、$u{桃仁}$w{二十枚}、$u{䗪虫}$w{二十枚 (去足)}。 </p>\n<p></p>\n<p>      右三味，末之，炼蜜和丸，以酒一升，水一升，煮取八合，顿服之，血下如豚肝愈。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":285,"yaoCount":3,"drinkNum":2,"yaoList":["大黄","桃仁","䗪虫"],"fangList":[],"fangYaoList":[{"yaoId":"To31b37bc6Z","amount":"三两","weight":null,"suffix":null,"showName":"大黄","extraProcess":null},{"yaoId":"k2cI79Wat6h","amount":"二十枚","weight":null,"suffix":null,"showName":"桃仁","extraProcess":null},{"yaoId":"nMnl8EhuWTn","amount":"二十枚 (去足)","weight":null,"suffix":null,"showName":"䗪虫","extraProcess":null}]}}', '2024-12-17T06:56:33.000Z', '2024-12-17T06:56:33.000Z', '2024-12-17T06:56:33.000Z', '$u{大黄}$w{三两}、$u{桃仁}$w{二十枚}、$u{䗪虫}$w{二十枚 (去足)}。 右三味，末之，炼蜜和丸，以酒一升，水一升，煮取八合，顿服之，血下如豚肝愈。', '2024-12-17T06:56:33.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
