INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DeVEeLxmsVg', 1, '{"title":"括蒌薤白白酒汤","description":"<p>$u{括蒌实}$w{一枚 (捣)}、$u{薤白}$w{半斤}、$u{白酒}$w{七升}。</p>\n<p></p>\n<p>        右三味，同煮取二升，分温再服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":295,"yaoCount":3,"drinkNum":2,"yaoList":["括蒌实","薤白","白酒"],"fangList":[],"fangYaoList":[{"yaoId":null,"amount":"一枚 (捣)","weight":null,"suffix":null,"showName":"括蒌实","extraProcess":null},{"yaoId":"PLFElISYWYO","amount":"半斤","weight":null,"suffix":null,"showName":"薤白","extraProcess":null},{"yaoId":null,"amount":"七升","weight":null,"suffix":null,"showName":"白酒","extraProcess":null}]}}', '2024-12-17T07:19:17.000Z', '2024-12-17T07:19:17.000Z', '2024-12-17T07:19:17.000Z', '$u{括蒌实}$w{一枚 (捣)}、$u{薤白}$w{半斤}、$u{白酒}$w{七升}。 右三味，同煮取二升，分温再服。', '2024-12-17T07:19:17.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
