INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3KAvbsXVqLG', 1, '{"title":"九痛丸","description":"<p>$u{附子}$w{三两}、$u{狼毒}$w{四两}、$u{巴豆}$w{一两 (去皮心熬研如脂)}、$u{人参}$w{一两}、$u{干姜}$w{一两}、$u{吴茱萸}$w{一两}。</p>\n<p></p>\n<p>           右六味，末之，蜜丸如梧桐子大，酒下，强人初服三丸，日三服，弱者二二丸。兼治卒中恶，腹胀痛，口不能言，又治连年积冷，流注，心胸痛，冷气上冲，落马，坠车，血疾等，皆主之；忌口如常法。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":305,"yaoCount":6,"drinkNum":3,"yaoList":["附子","狼毒","巴豆","人参","干姜","吴茱萸"],"fangList":[],"fangYaoList":[{"yaoId":"jT011T7yIVO","amount":"三两","weight":null,"suffix":null,"showName":"附子","extraProcess":null},{"yaoId":null,"amount":"四两","weight":null,"suffix":null,"showName":"狼毒","extraProcess":null},{"yaoId":"1n7R7kiLFv1","amount":"一两 (去皮心熬研如脂)","weight":null,"suffix":null,"showName":"巴豆","extraProcess":null},{"yaoId":"GIXSHBaFv0L","amount":"一两","weight":null,"suffix":null,"showName":"人参","extraProcess":null},{"yaoId":"0p1dUWRsS6D","amount":"一两","weight":null,"suffix":null,"showName":"干姜","extraProcess":null},{"yaoId":"ZJN7O318dPD","amount":"一两","weight":null,"suffix":null,"showName":"吴茱萸","extraProcess":null}]}}', '2024-12-17T07:36:11.000Z', '2024-12-17T07:36:11.000Z', '2024-12-17T07:36:11.000Z', '$u{附子}$w{三两}、$u{狼毒}$w{四两}、$u{巴豆}$w{一两 (去皮心熬研如脂)}、$u{人参}$w{一两}、$u{干姜}$w{一两}、$u{吴茱萸}$w{一两}。 右六味，末之，蜜丸如梧桐子大，酒下，强人初服三丸，日三服，弱者二二丸。兼治卒中恶，腹胀痛，口不能言，又治连年积冷，流注，心胸痛，冷气上冲，落马，坠车，血疾等，皆主之；忌口如常法。', '2024-12-17T07:36:11.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ti0hrD4fPFs', 1, '{"title":"桂枝茯苓丸","description":"<p>$u{桂枝}、$u{茯苓}、$u{牡丹}、$u{桃仁}、$u{芍药}$w{各等分}。</p>\n<p></p>\n<p>         右五味，末之，炼蜜为丸，如兔屎大，每日食前服一丸，不知可渐加至三丸。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":306,"yaoCount":5,"drinkNum":1,"yaoList":["桂枝","茯苓","牡丹","桃仁","芍药"],"fangList":[],"fangYaoList":[{"yaoId":"7S7n1dzieYK","amount":null,"weight":null,"suffix":null,"showName":"桂枝","extraProcess":null},{"yaoId":"VHE7Y68l232","amount":null,"weight":null,"suffix":null,"showName":"茯苓","extraProcess":null},{"yaoId":null,"amount":null,"weight":null,"suffix":null,"showName":"牡丹","extraProcess":null},{"yaoId":"k2cI79Wat6h","amount":null,"weight":null,"suffix":null,"showName":"桃仁","extraProcess":null},{"yaoId":"Ro0664U6sTQ","amount":"各等分","weight":null,"suffix":null,"showName":"芍药","extraProcess":null}]}}', '2024-12-17T07:43:53.000Z', '2024-12-17T07:43:53.000Z', '2024-12-17T07:43:53.000Z', '$u{桂枝}、$u{茯苓}、$u{牡丹}、$u{桃仁}、$u{芍药}$w{各等分}。 右五味，末之，炼蜜为丸，如兔屎大，每日食前服一丸，不知可渐加至三丸。', '2024-12-17T07:43:53.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
